require('dotenv').config();
const mongoose=require('mongoose');const bcrypt=require('bcrypt');const crypto=require('crypto');const User=require('../models/User');
(async()=>{try{if(!process.env.MONGODB_URI)throw new Error('MONGODB_URI is required.');const email=String(process.env.BOOTSTRAP_ADMIN_EMAIL||'').trim().toLowerCase();const password=String(process.env.BOOTSTRAP_ADMIN_PASSWORD||'');const name=String(process.env.BOOTSTRAP_ADMIN_NAME||'Administrator').trim();if(!email||!password)throw new Error('Set BOOTSTRAP_ADMIN_EMAIL and BOOTSTRAP_ADMIN_PASSWORD before running this script.');if(password.length<12)throw new Error('Admin password must be at least 12 characters.');await mongoose.connect(process.env.MONGODB_URI);let u=await User.findOne({email}).select('+passwordHash');if(u){u.role='super_admin';u.status='active';u.passwordHash=await bcrypt.hash(password,Number(process.env.BCRYPT_ROUNDS||12));u.sessionVersion=(u.sessionVersion||0)+1;if(!u.referralCode)u.referralCode=crypto.randomBytes(5).toString('hex').toUpperCase();await u.save();}else{let code;do{code=crypto.randomBytes(5).toString('hex').toUpperCase();}while(await User.exists({referralCode:code}));u=await User.create({name,email,passwordHash:await bcrypt.hash(password,Number(process.env.BCRYPT_ROUNDS||12)),referralCode:code,status:'active',role:'super_admin'});}console.log(`Admin ready: ${u.email}`);console.log(`Invite code: ${u.referralCode}`);const {generateSecret}=require('../services/totp'); if(!u.twoFactorEnabled){u.twoFactorSecret=generateSecret();u.twoFactorEnabled=true;u.twoFactorVerifiedAt=new Date();await u.save();} console.log('Super Admin ready with mandatory 2FA. Secret: '+u.twoFactorSecret);console.log('Remove BOOTSTRAP_ADMIN_PASSWORD from the environment after use.');}catch(e){console.error(e.message);process.exitCode=1;}finally{await mongoose.disconnect();}})();
